/* FrameOps interactive prototype. Role switching is NOT authentication. */
const state = { data:null, job:null, view:'storefront', role:'Admin', tab:'journey', filter:'All', search:'', homeownerId:'F-1008', loading:false };
const $ = selector => document.querySelector(selector);
const esc = value => String(value??'').replace(/[&<>"']/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money = n => Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const moneyPrecise = n => Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'});
const dateStr = d => { if(!d) return 'Not set'; const x = new Date((String(d).length===10?d+'T12:00:00':d)); return Number.isNaN(x.getTime())?esc(d):x.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}); };
const today = () => new Date().toLocaleDateString('en-CA');
const phases = [
  {label:'Lead',top:0}, {label:'Measurement',top:2}, {label:'Proposal',top:4}, {label:'Contract',top:6},
  {label:'Materials',top:8}, {label:'Installation',top:10}, {label:'Closeout',top:12}
];
const stage = name => state.data?.stages.indexOf(name)??0;
const stageColor = name => ['Closed','QA Passed','Materials Received','Funding Cleared'].includes(name)?'green':name==='Installed'?'orange':name==='New Lead'?'blue':name==='Contract Signed'||name==='Materials Ordered'?'orange':'blue';
const pill = (label,variant='')=>`<span class="status ${variant}">${esc(label)}</span>`;
const visibleTo = roles => state.role==='Admin'||roles.includes(state.role);
const roleFor = {add_opening:['Sales','Measurement Tech'],qualify:['Front Desk','Sales'],schedule_measurement:['Front Desk','Sales'],complete_measurement:['Measurement Tech'],send_proposal:['Sales'],accept_proposal:['Sales','Homeowner'],sign_contract:['Sales','Homeowner'],finance_update:['Accountant','Financing'],record_payment:['Accountant'],place_order:['Installation Manager'],materials_received:['Vendor','Installation Manager'],schedule_install:['Installation Manager'],installation_complete:['Service Tech','Installation Manager'],qa_passed:['Service Tech','Installation Manager'],close_job:['Accountant'],insurance_update:['Installation Manager','Accountant'],permit_update:['Installation Manager'],service_request:['Homeowner','Front Desk','Service Tech','Customer Service','Warranty Coordinator'],note:['Admin','Front Desk','Sales','Measurement Tech','Accountant','Vendor','Installation Manager','Service Tech','Homeowner'],set_priority:['Front Desk','Sales']};
const actionNames = {add_opening:'Add window / door opening',qualify:'Qualify lead',schedule_measurement:'Book measurement',complete_measurement:'Record measurements',send_proposal:'Send proposal',accept_proposal:'Approve proposal',sign_contract:'Record signed contract',finance_update:'Update financing',record_payment:'Record payment',place_order:'Create vendor purchase order',materials_received:'Confirm materials received',schedule_install:'Schedule installation',installation_complete:'Complete installation',qa_passed:'Approve quality walkthrough',close_job:'Close job & activate warranty',insurance_update:'Update insurance check',permit_update:'Update permit check',service_request:'Open service request',note:'Add team note',set_priority:'Change priority'};
const nextActions = {
  'New Lead':{code:'qualify',label:'Qualify the homeowner inquiry',description:'Verify property, contact information, product needs and timeline.'},
  'Qualified':{code:'schedule_measurement',label:'Arrange an on-site measurement',description:'Sales or front desk books the visit and triggers the technician’s task.'},
  'Measurement Scheduled':{code:'complete_measurement',label:'Capture verified field measurements',description:'Record accurate opening dimensions and installation constraints.'},
  'Measurements Complete':{code:'send_proposal',label:'Send a detailed homeowner proposal',description:'Price products and installation using the confirmed measurements.'},
  'Proposal Sent':{code:'accept_proposal',label:'Record homeowner proposal approval',description:'Confirm the homeowner accepts the project scope and estimate.'},
  'Proposal Approved':{code:'sign_contract',label:'Complete the contract and payment plan',description:'Record an accepted contract, deposit requirement and financing choice.'},
  'Contract Signed':{code:'record_payment',label:'Verify project funding',description:'Accountant records the deposit or financing approval before procurement.'},
  'Funding Cleared':{code:'place_order',label:'Release the vendor purchase order',description:'Order approved windows and doors with a supplier and delivery ETA.'},
  'Materials Ordered':{code:'materials_received',label:'Confirm ordered products have arrived',description:'Vendor or installation manager confirms the materials are ready.'},
  'Materials Received':{code:'schedule_install',label:'Schedule installation and crew',description:'Check materials, permits, insurance and homeowner availability.'},
  'Installation Scheduled':{code:'installation_complete',label:'Record completed installation',description:'Field team logs work completed, photos, exceptions and clean-up.'},
  'Installed':{code:'qa_passed',label:'Perform the quality walkthrough',description:'Check fit, finish, operation, punch-list and customer handoff.'},
  'QA Passed':{code:'close_job',label:'Reconcile the account and activate warranty',description:'Close only after site QA is approved and the final balance is cleared.'},
  'Closed':{code:'service_request',label:'Job closed — aftercare available',description:'The homeowner may submit a service request against their warranty.'}
};
const roleDescriptions = {
  'Admin':'Full portfolio visibility, escalations, team workload and operational oversight.',
  'Front Desk':'New inquiries, lead qualification, appointment coordination and homeowner updates.',
  'Sales':'Consultations, proposals, approvals, contracts and customer follow-ups.',
  'Measurement Tech':'Field measurement appointments, opening dimensions and site constraints.',
  'Accountant':'Deposits, financing statuses, payment records, final balance and job closeout.',
  'Vendor':'Material orders, supplier ETAs and receipt confirmation.',
  'Installation Manager':'Purchase orders, permits, insurance, materials, crews and installation scheduling.',
  'Service Tech':'Installation completion, QA, punch lists and warranty service requests.',
  'Homeowner':'Project milestones, proposal acceptance, contract confirmation and service requests.',
  'Financing':'Track externally approved funding decisions and release-to-procurement gates.',
  'Customer Service':'Resolve customer questions, coordinate post-installation service and satisfaction.',
  'Warranty Coordinator':'Manage post-closeout warranty cases, customer feedback and aftercare.'
};
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-root').replaceChildren(el);setTimeout(()=>{if(el.parentNode)el.remove()},3600)}
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});let data;try{data=await r.json()}catch{throw new Error('Server response could not be read')}if(!r.ok)throw new Error(data.error||'Request failed');return data}
async function load(){state.data=await api('/api/bootstrap');updateHeader();render()}
function updateHeader(){if(!state.data)return;const unread=state.data.notifications.filter(n=>!n.read_at&&(state.role==='Admin'||n.role===state.role)).length;$('#nav-job-count').textContent=state.data.jobs.length;$('#nav-notif-count').textContent=unread;$('#top-notif-count').textContent=unread;$('#top-notif-count').style.display=unread?'grid':'none';$('#role-avatar').textContent=state.role.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();const crumbs={overview:'Admin Dashboard',storefront:'Customer Storefront',frontdesk:'Front Desk',leads:'Leads & Sales',measurements:'Measurements',vendors:'Vendors',installation:'Installation',financing:'Financing',accounting:'Accounting',warranty:'Warranty', 'customer-service':'Customer Service',documents:'Documents & Invoices',jobs:'Leads & Jobs',tasks:'My Work Queue',notifications:'Notifications',homeowner:'Homeowner Portal',workflow:'Workflow Design','quick-quote':'Fast Quote','customer-hub':'Customer Project Portal','quote-operations':'Quote & Schedule Console','demo-journey':'Live Journey Simulator','business-settings':'Business & Social Settings',job:state.job?state.job.id:'Job Details'};$('#crumb').textContent=crumbs[state.view]||'Overview';document.querySelectorAll('.nav-link').forEach(el=>el.classList.toggle('active',el.dataset.nav===state.view));}
function go(view){state.view=view;state.filter='All';state.search='';$('#sidebar').classList.remove('open');$('#overlay')?.classList.remove('open');updateHeader();render();window.scrollTo({top:0,behavior:'instant'});}
async function openJob(id){try{state.job=await api('/api/jobs/'+encodeURIComponent(id));state.tab='journey';go('job')}catch(e){toast(e.message,true)}}
function sectionHead(eyebrow,title,subtitle,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${buttons?`<div class="page-actions">${buttons}</div>`:''}</div>`}
function stats(){const jobs=state.data.jobs,open=jobs.filter(j=>j.stage!=='Closed'),moneyInFlight=open.reduce((n,j)=>n+Number(j.quote_total||0),0),blocked=jobs.filter(j=>['Contract Signed','Installed','QA Passed'].includes(j.stage)).length,queue=state.data.tasks.filter(t=>state.role==='Admin'||t.role===state.role).length;
return `<div class="stats-grid"><div class="stat-card"><div class="stat-head">Active projects <span class="stat-ic">▦</span></div><div class="stat-number">${open.length}</div><div class="stat-caption">Jobs across the lifecycle</div></div><div class="stat-card"><div class="stat-head">Open work items <span class="stat-ic">☷</span></div><div class="stat-number">${queue}</div><div class="stat-caption">${state.role==='Admin'?'Across all departments':'Assigned to your role'}</div></div><div class="stat-card"><div class="stat-head">Quoted project value <span class="stat-ic">＄</span></div><div class="stat-number">${money(moneyInFlight)}</div><div class="stat-caption">Open projects, not revenue</div></div><div class="stat-card"><div class="stat-head">Requiring attention <span class="stat-ic">◎</span></div><div class="stat-number">${blocked}</div><div class="stat-caption">Funding, field QA or closeout</div></div></div>`}
function pipeline(){const cats=[['New / qualifying',['New Lead','Qualified']],['Site visit / measure',['Measurement Scheduled','Measurements Complete']],['Sales / contracting',['Proposal Sent','Proposal Approved','Contract Signed']],['Materials / funding',['Funding Cleared','Materials Ordered','Materials Received']],['Installation / QA',['Installation Scheduled','Installed','QA Passed']],['Closed / warranty',['Closed']]];const total=state.data.jobs.length;return cats.map(([label,names])=>{const n=state.data.jobs.filter(j=>names.includes(j.stage)).length;return `<div class="pipeline-row"><div class="pipeline-label">${label}</div><div class="bar-track"><div class="bar-fill" style="width:${total?100*n/total:0}%"></div></div><div class="bar-count">${n}</div></div>`}).join('')}
function blockers(){const priority=[];for(const j of state.data.jobs){if(j.stage==='Contract Signed')priority.push([j,'Deposit or financing needs verification','＄']);else if(j.stage==='Installed')priority.push([j,'Field QA and final balance pending','!']);else if(j.stage==='QA Passed')priority.push([j,'Payment reconciliation and closeout','!']);else if(j.stage==='Materials Ordered')priority.push([j,'Awaiting materials from vendor','□']);else if(j.stage==='New Lead')priority.push([j,'New lead needs follow-up','⌁']);}
return priority.slice(0,5).map(([j,desc,icon])=>`<button class="blocker" data-job="${esc(j.id)}"><span class="blocker-icon">${icon}</span><span><strong>${esc(j.homeowner)}</strong><small>${esc(desc)} · ${esc(j.id)}</small></span><span class="arrow">›</span></button>`).join('')||'<div class="empty-state">No major blockers</div>'}
function tableRows(jobs,limit=0){return (limit?jobs.slice(0,limit):jobs).map(j=>`<tr class="click-row" data-job="${esc(j.id)}"><td><div class="main-cell">${esc(j.homeowner)}</div><div class="sub-cell">${esc(j.id)} · ${esc(j.service_type)}</div></td><td>${esc(j.address.split(',').slice(-2).join(',').trim())}</td><td>${pill(j.stage,stageColor(j.stage))}</td><td>${esc(j.assigned_sales)}</td><td>${j.quote_total?money(j.quote_total):'—'}</td><td>${j.priority==='Urgent'?pill('Urgent','red'):j.priority==='High'?pill('High','orange'):pill('Normal')}</td><td style="font-weight:700;color:#5573bf">View ›</td></tr>`).join('')}
function tablePanel(jobs,limit,showHead=true){return `<section class="panel">${showHead?`<div class="panel-pad" style="padding-bottom:0"><div class="panel-heading" style="margin-bottom:4px"><div><h2>Recent jobs</h2><p>From initial inquiry through installation and warranty</p></div><button class="text-link" data-nav="jobs">View all jobs →</button></div></div>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Homeowner / Job</th><th>Location</th><th>Stage</th><th>Sales owner</th><th>Quote</th><th>Priority</th><th></th></tr></thead><tbody>${tableRows(jobs,limit)}</tbody></table></div></section>`}
function renderOverview(){const tasks=state.data.tasks.filter(t=>state.role==='Admin'||t.role===state.role);return `<div class="page">${sectionHead('Operations command center','Good to see you.','Monitor every homeowner project and coordinate the next handoff.',`<button class="button" data-nav="tasks">View my queue</button><button class="button primary" data-modal="newLead">＋ New lead</button>`)}${stats()}<div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Project pipeline</h2><p>All active and completed job stages</p></div>${pill(state.data.jobs.length+' total jobs')}</div>${pipeline()}</section><section class="panel panel-pad"><div class="panel-heading"><div><h2>Needs attention</h2><p>Actionable handoffs and potential bottlenecks</p></div></div><div class="blockers">${blockers()}</div></section></div><div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-heading"><div><h2>${state.role==='Admin'?'Next team actions':'Your next actions'}</h2><p>${tasks.length} open work items ${state.role==='Admin'?'across all roles':'for '+esc(state.role)}</p></div><button class="text-link" data-nav="tasks">View work queue →</button></div><div class="task-list">${tasks.slice(0,4).map(taskCard).join('')||empty('Nothing assigned','There are no open tasks for this role.')}</div></section><section class="panel panel-pad"><div class="panel-heading"><div><h2>How work moves</h2><p>One record, multiple teams</p></div></div><div class="timeline"><div class="timeline-item"><strong>Lead & sales</strong><p>Front desk → sales → measurement technician</p></div><div class="timeline-item"><strong>Contract & funding</strong><p>Homeowner → sales → accountant</p></div><div class="timeline-item"><strong>Delivery & installation</strong><p>Installation manager → vendor → field crew</p></div><div class="timeline-item"><strong>Closeout & aftercare</strong><p>Service technician → accountant → homeowner</p></div></div><button class="button light small" data-nav="workflow">Explore full workflow</button></section></div>${tablePanel(state.data.jobs,6)}</div>`}
function filterMatch(j){const q=state.search.toLowerCase();let match=!q||[j.homeowner,j.id,j.address,j.service_type,j.assigned_sales,j.stage].some(v=>String(v).toLowerCase().includes(q));if(state.filter==='All')return match;if(state.filter==='New Leads')return match&&['New Lead','Qualified'].includes(j.stage);if(state.filter==='Sales')return match&&['Measurement Scheduled','Measurements Complete','Proposal Sent','Proposal Approved','Contract Signed'].includes(j.stage);if(state.filter==='Operations')return match&&['Funding Cleared','Materials Ordered','Materials Received','Installation Scheduled','Installed','QA Passed'].includes(j.stage);if(state.filter==='Closed')return match&&j.stage==='Closed';return match}
function renderJobs(){const jobs=state.data.jobs.filter(filterMatch);const filterNames=['All','New Leads','Sales','Operations','Closed'];return `<div class="page">${sectionHead('Complete job pipeline','Leads & jobs','One source of truth for every homeowner and every department.',`<button class="button primary" data-modal="newLead">＋ Create lead</button>`)}<div class="toolbar"><label class="search-wrap">⌕ <input id="job-search" placeholder="Search homeowner, job ID, address..." value="${esc(state.search)}" autocomplete="off"></label><div class="filters">${filterNames.map(f=>`<button class="filter-pill ${state.filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div></div><div class="list-summary">${jobs.length} jobs shown · Click any record to open full history</div>${jobs.length?tablePanel(jobs,0,false):empty('No matching jobs','Try another filter or search term.')}</div>`}
function taskCard(t){return `<button class="task-item" data-job="${esc(t.job_id)}"><span class="task-check">✓</span><span class="task-info"><strong>${esc(t.title)}</strong><p>${esc(t.homeowner||'')} · ${esc(t.job_id)} · ${esc(t.detail||'No additional details')}</p></span><span class="task-meta">${pill(t.role==='Admin'?'Admin':t.role,'blue')}<small>${dateStr(t.due_date)}</small></span></button>`}
function empty(title,body){return `<div class="empty-state"><div class="empty-icon">◌</div><h3>${title}</h3><p>${body}</p></div>`}
function renderTasks(){const ts=state.data.tasks.filter(t=>state.role==='Admin'||t.role===state.role);return `<div class="page">${sectionHead('Role-specific execution','My work queue',esc(roleDescriptions[state.role])+ ' Actions are assigned to the accountable department.')}${statsQueue(ts)}<section class="panel panel-pad"><div class="panel-heading"><div><h2>Open assignments</h2><p>${ts.length} work items requiring follow-up</p></div></div><div class="task-list">${ts.length?ts.map(taskCard).join(''):empty('All caught up','No open work items for your selected role.')}</div></section></div>`}
function statsQueue(ts){const due=ts.filter(t=>t.due_date<=today()).length;return `<div class="stats-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));max-width:600px"><div class="stat-card"><div class="stat-head">Open assignments <span class="stat-ic">☷</span></div><div class="stat-number">${ts.length}</div><div class="stat-caption">Your current responsibility</div></div><div class="stat-card"><div class="stat-head">Due today / earlier <span class="stat-ic">◷</span></div><div class="stat-number">${due}</div><div class="stat-caption">Check and resolve priority items</div></div></div>`}
function renderNotifications(){const ns=state.data.notifications.filter(n=>state.role==='Admin'||n.role===state.role);const unread=ns.filter(n=>!n.read_at).length;return `<div class="page">${sectionHead('Cross-functional coordination','Notifications','In-app alerts generated when a job changes hands.',`<button class="button" data-read-notifications ${unread?'':'disabled'}>Mark all read</button>`)}<section class="panel">${ns.length?ns.map(n=>`<div class="notif-row ${n.read_at?'':'unread'}" data-job="${esc(n.job_id)}"><span class="notif-dot"></span><div class="notif-content"><strong>${esc(n.title)}</strong><p>${esc(n.detail||'Status updated')} · ${esc(n.job_id)} · ${esc(n.role)}</p><small>${dateStr(n.created_at)}</small></div><span style="color:#9aa9b9">›</span></div>`).join(''):empty('No alerts yet','Alerts appear after work is handed off to other teams.')}</section><div class="notice blue">This prototype records notifications inside the app. Email, SMS, and calendar delivery require separately configured integrations and permission rules.</div></div>`}
function can(code){return visibleTo(roleFor[code]||[])}
function jobActions(j){const a=[];const main=nextActions[j.stage];if(main&&can(main.code))a.push(main.code);if(j.stage==='Contract Signed'&&j.financing_type==='Financing requested'&&can('finance_update'))a.push('finance_update');if(state.data.stages.indexOf(j.stage)>=stage('Contract Signed')&&j.stage!=='Closed'&&j.balance>0&&j.quote_total&&can('record_payment')&&!a.includes('record_payment'))a.push('record_payment');if(state.data.stages.indexOf(j.stage)>=stage('Qualified')&&can('insurance_update'))a.push('insurance_update');if(state.data.stages.indexOf(j.stage)>=stage('Qualified')&&can('permit_update'))a.push('permit_update');if(stage(j.stage)<=stage('Measurements Complete')&&can('add_opening'))a.push('add_opening');if(can('set_priority'))a.push('set_priority');return [...new Set(a)]}
function actionButton(a,variant=''){return `<button class="button ${variant}" data-action="${esc(a)}">${a=== 'record_payment'?'＄ ':'＋ '}${esc(actionNames[a])}</button>`}
function milestones(j){const i=stage(j.stage);return `<div class="milestone-grid">${phases.map((p,n)=>{const done=i>=((phases[n+1]?.top??14));const current=i>=p.top&&!done;return `<div class="mile ${done?'done':current?'current':''}"><div class="mile-top"></div><span>${p.label}</span></div>`}).join('')}</div>`}
function nextStep(j){const n=nextActions[j.stage];return `<div class="next-card"><div class="next-label">Next milestone · ${pill(j.stage,stageColor(j.stage))}</div><h3>${esc(n.label)}</h3><p>${esc(n.description)}</p>${can(n.code)?`<div class="action-list">${actionButton(n.code,'primary')}</div>`:`<div style="font-size:12px;color:#6c7ea8;font-weight:700">Assigned role: ${(roleFor[n.code]||[]).join(' / ')}. Select that role to process the step.</div>`}</div>`}
function generalInfo(j){return `<div class="panel panel-pad"><div class="panel-heading"><div><h2>Homeowner & scope</h2><p>Customer and site details</p></div></div><div class="detail-row"><span>Homeowner</span><strong>${esc(j.homeowner)}</strong></div><div class="detail-row"><span>Project</span><strong>${esc(j.service_type)}</strong></div><div class="detail-row"><span>Property</span><strong>${esc(j.address)}</strong></div><div class="detail-row"><span>Telephone</span><strong>${esc(j.phone)}</strong></div><div class="detail-row"><span>Email</span><strong>${esc(j.email)}</strong></div><div class="detail-row"><span>Lead source</span><strong>${esc(j.lead_source)}</strong></div><div class="detail-row"><span>Sales owner</span><strong>${esc(j.assigned_sales)}</strong></div><div class="detail-row"><span>Created</span><strong>${dateStr(j.created_at)}</strong></div></div>`}
function journeyTab(j){const actions=jobActions(j);const open=j.tasks.filter(t=>t.status==='Open');return `<div class="detail-grid"><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Job lifecycle</h2><p>All teams work from the same job record</p></div></div>${milestones(j)}${nextStep(j)}${actions.filter(a=>a!==nextActions[j.stage].code).length?`<h3 class="section-heading" style="margin-top:25px;font-size:14px">Supporting actions</h3><div class="action-list">${actions.filter(a=>a!==nextActions[j.stage].code).map(a=>actionButton(a,'small')).join('')}</div>`:''}</section><section class="panel panel-pad section-gap"><div class="panel-heading"><div><h2>Team assignments</h2><p>${open.length} open action${open.length!==1?'s':''} attached to this job</p></div></div><div class="task-list">${open.length?open.map(t=>taskCard({...t,homeowner:j.homeowner})).join(''):empty('No open tasks','All assigned workflow steps have been completed.')}</div></section><section class="panel panel-pad section-gap"><div class="panel-heading"><div><h2>Field & fulfillment</h2></div></div><div class="two-col-info"><div class="info-block"><div class="detail-label">Measurements / field notes</div><p>${esc(j.measurement_notes||'Not yet recorded')}</p></div><div class="info-block"><div class="detail-label">Install / QA notes</div><p>${esc(j.install_notes||'Awaiting installation')}</p></div><div class="info-block"><div class="detail-label">Vendor</div><p>${esc(j.vendor_name||'Not selected')} ${j.vendor_order?'· '+esc(j.vendor_order):''}</p></div><div class="info-block"><div class="detail-label">Material delivery</div><p>${j.materials_received?'Received':j.vendor_eta?'Expected '+dateStr(j.vendor_eta):'Not yet ordered'}</p></div></div></section></div><div>${generalInfo(j)}<section class="panel panel-pad section-gap"><div class="panel-heading"><div><h2>Readiness checks</h2><p>Gate installation and closeout safely</p></div></div><div class="detail-row"><span>Contract</span><strong>${esc(j.contract_status)}</strong></div><div class="detail-row"><span>Funding plan</span><strong>${esc(j.financing_type)}</strong></div><div class="detail-row"><span>Financing</span><strong>${esc(j.financing_status)}</strong></div><div class="detail-row"><span>Contractor COI</span><strong>${esc(j.contractor_insurance)}</strong></div><div class="detail-row"><span>Permit</span><strong>${esc(j.permit_status)}</strong></div><div class="detail-row"><span>Installation</span><strong>${dateStr(j.install_date)}</strong></div><div class="detail-row"><span>Site QA</span><strong>${esc(j.qa_status)}</strong></div><div class="detail-row"><span>Warranty</span><strong>${esc(j.warranty_status)}</strong></div></section></div></div>`}
function openingsTab(j){
 const rows=j.openings||[];const estimate=rows.reduce((sum,r)=>sum+Number(r.unit_price||0)*Number(r.quantity||1),0);
 const canAdd=stage(j.stage)<=stage('Measurements Complete')&&can('add_opening');
 return `<div class="detail-grid"><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Openings & product specifications</h2><p>${rows.length} product line${rows.length!==1?'s':''} · Verified measurements are captured per location</p></div>${canAdd?`<button class="button primary small" data-action="add_opening">＋ Add opening</button>`:''}</div>${rows.length?`<div class="table-wrap"><table class="data-table" style="min-width:620px"><thead><tr><th>Location / Product</th><th>Qty</th><th>Width × Height</th><th>Frame / Glass</th><th>Est. product amount</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="main-cell">${esc(r.room)}</div><div class="sub-cell">${esc(r.product_type)}${r.notes?' · '+esc(r.notes):''}</div></td><td>${r.quantity}</td><td>${r.width} × ${r.height} in</td><td>${esc(r.frame||'—')}<div class="sub-cell">${esc(r.glazing||'—')}</div></td><td>${r.unit_price?moneyPrecise(r.unit_price*r.quantity):'Not priced'}</td></tr>`).join('')}</tbody></table></div><div class="detail-row" style="padding:17px 2px 0"><span>Estimated product line values</span><strong>${moneyPrecise(estimate)}</strong></div>`:empty('No openings entered','Sales or a measurement technician can add a window or door opening before quoting.')}<div class="notice blue">Opening sizes are in inches. Estimated product amounts do not automatically equal the homeowner proposal; installation labor, disposal, tax and other approved costs may differ.</div></section></div><div><section class="panel panel-pad"><h2 class="section-heading">Site measurement report</h2><p style="font-size:12px;color:#74849a;line-height:1.8">${esc(j.measurement_notes||'No field measurements recorded yet.')}</p><div class="detail-row"><span>Current lifecycle stage</span><strong>${esc(j.stage)}</strong></div><div class="detail-row"><span>Proposal amount</span><strong>${j.quote_total?moneyPrecise(j.quote_total):'Not issued'}</strong></div><div class="detail-row"><span>Record revisions</span><strong>${stage(j.stage)>=stage('Proposal Sent')?'Locked — change order required':'Open for additions'}</strong></div></section><section class="panel panel-pad section-gap"><h2 class="section-heading">Recommended field data</h2><p style="font-size:12px;color:#74849a;line-height:1.8">Room, opening type, quantity, measured width and height, frame material, glazing, product price, installation obstacles, photos and safety / code requirements. Formal versioning and approval are future production features.</p></section></div></div>`
}
function financeTab(j){const pct=j.quote_total?Math.min(100,100*j.paid/j.quote_total):0;return `<div class="detail-grid"><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Job financials</h2><p>Contract, deposits, financing and outstanding balance</p></div><div class="action-list">${can('record_payment')&&j.quote_total&&stage(j.stage)>=stage('Contract Signed')&&j.stage!=='Closed'?actionButton('record_payment','small primary'):''}${can('finance_update')&&j.financing_type==='Financing requested'?actionButton('finance_update','small'):''}</div></div><div class="card-grid"><div class="info-block"><div class="detail-label">Agreed project total</div><div class="money-big">${moneyPrecise(j.quote_total)}</div></div><div class="info-block"><div class="detail-label">Remaining balance</div><div class="money-big">${moneyPrecise(j.balance)}</div></div></div><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div><div class="muted" style="font-size:11px">${Math.round(pct)}% recorded as received · ${moneyPrecise(j.paid)} to date</div><div class="detail-row"><span>Required initial deposit</span><strong>${moneyPrecise(j.deposit_required)}</strong></div><div class="detail-row"><span>Payment method</span><strong>${esc(j.financing_type)}</strong></div><div class="detail-row"><span>Financing application</span><strong>${esc(j.financing_status)}</strong></div><div class="notice">Entries below are manual payment records. This prototype does not process cards, contact lenders, verify a bank deposit, or issue real receipts.</div></section><section class="panel panel-pad section-gap"><div class="panel-heading"><div><h2>Payment ledger</h2><p>Recorded transactions associated with this project</p></div></div>${j.payments.length?j.payments.map(p=>`<div class="payment-card"><span><strong>${esc(p.kind||'Payment')}</strong><small>${dateStr(p.created_at)} · ${esc(p.method||'Manual')} · ${esc(p.reference||'No reference')}</small></span><strong style="color:#187c64">+${moneyPrecise(p.amount)}</strong></div>`).join(''):empty('No payments recorded','Payments appear after the accountant records funds received.')}</section></div><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Approval & compliance</h2></div></div><div class="detail-row"><span>Signed contract</span><strong>${esc(j.contract_status)}</strong></div><div class="detail-row"><span>Vendor PO</span><strong>${esc(j.vendor_order||'Not yet created')}</strong></div><div class="detail-row"><span>Insurance verification</span><strong>${esc(j.contractor_insurance)}</strong></div><div class="detail-row"><span>Permit readiness</span><strong>${esc(j.permit_status)}</strong></div></section></div></div>`}
function docsTab(j){return `<div class="detail-grid"><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Job documents</h2><p>Contracts, photos, measurements, permits, supplier and warranty files</p></div><button class="button primary small" data-modal="upload">＋ Upload file</button></div><div class="doc-list">${j.documents.length?j.documents.map(d=>`<div class="doc-row"><span class="doc-icon">▤</span><span style="min-width:0;flex:1"><strong>${esc(d.name)}</strong><small>${esc(d.doc_type)} · ${dateStr(d.created_at)} · ${esc(d.added_by)}</small></span>${d.stored_name?`<a class="button small" href="/api/documents/${d.id}" target="_blank" rel="noopener">Download</a>`:`<span class="status">Record only</span>`}</div>`).join(''):empty('No documents yet','Add relevant files to complete the job record.')}</div></section></div><div><section class="panel panel-pad"><h2 class="section-heading">Document checklist</h2>${['Homeowner inquiry / site photos','Measurement worksheet','Proposal & revisions','Signed contract & change orders','Financing / payment records','Insurance COI & permits','Vendor PO & delivery confirmation','Installation photos & QA','Warranty terms & handover'].map((name,i)=>`<div class="detail-row"><span>${name}</span><strong style="color:#8896a5">${i<j.documents.length?'Review file list':'As applicable'}</strong></div>`).join('')}</section><div class="notice">Uploaded files are stored on the server disk for demo purposes. A production deployment requires private object storage, retention rules, malware scanning, audit trails, and role-based document access.</div></div></div>`}
function activityTab(j){return `<div class="detail-grid"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Complete activity timeline</h2><p>Recorded work and cross-department handoffs</p></div></div><div class="timeline">${j.events.map(e=>`<div class="timeline-item"><strong>${esc(e.label)}</strong><p>${esc(e.detail)}</p><small>${esc(e.actor)} · ${dateStr(e.created_at)}</small></div>`).join('')}</div></section><section class="panel panel-pad" style="align-self:start"><h2 class="section-heading">Leave an internal update</h2><p style="font-size:12px;color:#8492a4;line-height:1.6;margin-bottom:17px">Record an exception, homeowner callback, vendor update or coordination note without changing the lifecycle stage.</p>${actionButton('note','small primary')}</section></div>`}
function renderJob(){const j=state.job;if(!j)return '';const tabs=['journey','openings','financials','documents','activity'];const labels=['Work & Journey','Products & Measurements','Financials','Documents','Activity'];const content={journey:journeyTab,openings:openingsTab,financials:financeTab,documents:docsTab,activity:activityTab};return `<div class="page"><button class="job-back" data-nav="jobs">← All leads & jobs</button><div class="page-heading job-heading"><div class="job-title"><div class="job-ref">${esc(j.id)} · ${pill(j.priority+' priority',j.priority==='Urgent'?'red':j.priority==='High'?'orange':'')}</div><h1>${esc(j.homeowner)}</h1><p>${esc(j.service_type)} · ${esc(j.address)}</p></div><div class="page-actions">${pill(j.stage,stageColor(j.stage))}<button class="button" data-action="note">＋ Add note</button><button class="button primary" data-modal="upload">▤ Upload file</button></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-head">Project estimate <span class="stat-ic">＄</span></div><div class="stat-number">${j.quote_total?money(j.quote_total):'Pending'}</div><div class="stat-caption">Proposal / signed contract value</div></div><div class="stat-card"><div class="stat-head">Amount received <span class="stat-ic">✓</span></div><div class="stat-number">${money(j.paid)}</div><div class="stat-caption">Recorded by accounting</div></div><div class="stat-card"><div class="stat-head">Tasks open <span class="stat-ic">☷</span></div><div class="stat-number">${j.tasks.filter(t=>t.status==='Open').length}</div><div class="stat-caption">Across every assigned team</div></div><div class="stat-card"><div class="stat-head">Installation date <span class="stat-ic">▤</span></div><div class="stat-number" style="font-size:20px">${j.install_date?dateStr(j.install_date):'Not scheduled'}</div><div class="stat-caption">Homeowner appointment</div></div></div><nav class="job-tabs">${tabs.map((t,i)=>`<button class="job-tab ${state.tab===t?'active':''}" data-tab="${t}">${labels[i]}</button>`).join('')}</nav>${content[state.tab](j)}</div>`}
function renderHomeowner(){const j=state.data.jobs.find(x=>x.id===state.homeownerId)||state.data.jobs[0];if(!j)return '';const n=nextActions[j.stage];const mayAct=['accept_proposal','sign_contract','service_request'].includes(n.code);return `<div class="page">${sectionHead('Self-service experience','Homeowner portal','A simplified view of the same project record; no separate status spreadsheet.')}<div class="toolbar"><div class="muted" style="font-size:12px">Preview a fictional homeowner account</div><select id="homeowner-select" class="home-select" aria-label="Select demo homeowner">${state.data.jobs.map(x=>`<option value="${esc(x.id)}" ${x.id===j.id?'selected':''}>${esc(x.homeowner)} · ${esc(x.id)}</option>`).join('')}</select></div><div class="home-banner"><div><div class="eyebrow" style="color:#9cb9ff">YOUR PROJECT ${esc(j.id)}</div><h2>Hello, ${esc(j.homeowner.split(' ')[0])}.</h2><p>Track your ${esc(j.service_type.toLowerCase())} project, review milestones and contact the service team.<br>Property: ${esc(j.address)}</p></div><div class="home-illustration">⌂</div></div><div class="detail-grid"><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Project progress</h2><p>Current status: ${esc(j.stage)}</p></div>${pill(j.stage,stageColor(j.stage))}</div>${milestones(j)}<div class="next-card"><div class="next-label">Latest step</div><h3>${esc(n.label)}</h3><p>${esc(n.description)}</p>${mayAct?`<button class="button primary small" data-homeowner-action="${esc(n.code)}">${esc(actionNames[n.code])}</button>`:`<div style="color:#6380b5;font-size:12px;font-weight:680">The team will update you when the next milestone is complete.</div>`}</div></section><section class="panel panel-pad section-gap"><h2 class="section-heading">What happens next?</h2><p style="color:#7b899b;font-size:12px;line-height:1.8">Your project team coordinates field measurements, approved materials, installation and completion behind the scenes. Contact the front desk if a date or site detail changes.</p>${j.stage==='Closed'?`<div style="margin-top:18px"><button class="button" data-homeowner-action="service_request">Request warranty service</button></div>`:''}</section></div><div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Project details</h2></div></div><div class="detail-row"><span>Project</span><strong>${esc(j.service_type)}</strong></div><div class="detail-row"><span>Project total</span><strong>${j.quote_total?moneyPrecise(j.quote_total):'Awaiting proposal'}</strong></div><div class="detail-row"><span>Recorded payments</span><strong>${moneyPrecise(j.paid)}</strong></div><div class="detail-row"><span>Installation</span><strong>${dateStr(j.install_date)}</strong></div><div class="detail-row"><span>Warranty</span><strong>${esc(j.warranty_status)}</strong></div><div class="detail-row"><span>Service contact</span><strong>Contact front desk</strong></div></section>${j.warranty_status==='Active'?`<div class="notice blue">Warranty information: ${esc(j.warranty_terms)}. Coverage and service eligibility depend on the actual signed agreement.</div>`:''}</div></div><div class="notice">Prototype preview only: selecting a homeowner here does not authenticate them. A real portal needs verified homeowner sign-in and access restricted to their own jobs.</div></div>`}
function renderWorkflow(){const phasesData=[['Capture & qualify','Front desk gathers lead, address, source, urgency and initial product scope.'],['Sell & measure','Sales consults; field technician verifies opening sizes; revised scope feeds pricing.'],['Approve & fund','Homeowner reviews estimate, signs contract, pays deposit or applies for financing.'],['Procure & prepare','Installation manager releases PO, supplier confirms shipment; permits and COI verified.'],['Install & inspect','Crew scheduled, field installation captured, QA and punch list completed.'],['Collect & close','Accountant reconciles balance, warranty documents issued, homeowner handover recorded.'],['Service & warranty','Post-install issues become tracked service requests linked to the original job.']];return `<div class="page">${sectionHead('End-to-end system architecture','How FrameOps works','Design blueprint for a client-owned window and door operations platform.')}<div class="workflow-phases">${phasesData.map((p,i)=>`<div class="phase-card"><div class="phase-no">STEP ${String(i+1).padStart(2,'0')}</div><h3>${esc(p[0])}</h3><p>${esc(p[1])}</p></div>`).join('')}</div><section class="panel panel-pad"><div class="panel-heading"><div><h2>Responsibility by role</h2><p>Departments have defined tasks, data access and action permissions</p></div></div><div class="role-grid">${Object.keys(roleDescriptions).map(role=>`<div class="role-tile"><strong>${esc(role)}</strong><p>${esc(roleDescriptions[role])}</p></div>`).join('')}</div></section><div class="dashboard-grid section-gap"><section class="panel panel-pad"><h2 class="section-heading">Business rules demonstrated</h2><div class="timeline"><div class="timeline-item"><strong>No purchasing without funding</strong><p>Vendor PO is gated by deposit threshold or financing approval.</p></div><div class="timeline-item"><strong>No installation without readiness checks</strong><p>Materials must be received; any required permit and COI must be verified.</p></div><div class="timeline-item"><strong>No warranty activation before closeout</strong><p>Final QA must pass and the full contracted payment must be recorded.</p></div><div class="timeline-item"><strong>Each handoff creates work</strong><p>Assigned tasks, in-app notifications and a common event history follow the job.</p></div></div></section><section class="panel panel-pad"><h2 class="section-heading">Production integrations — not connected</h2><div class="detail-row"><span>Lead sources</span><strong>Website, phone, referrals, ads</strong></div><div class="detail-row"><span>Communications</span><strong>Email, SMS, calls, calendar</strong></div><div class="detail-row"><span>Contracts</span><strong>E-signature</strong></div><div class="detail-row"><span>Payments & financing</span><strong>Processor / lender APIs</strong></div><div class="detail-row"><span>Supplier</span><strong>PO / ETA interfaces</strong></div><div class="detail-row"><span>Documents</span><strong>Private object storage</strong></div><div class="notice blue">The current prototype runs with an embedded SQLite database, fictional customers, manually recorded transactions, and role switching for evaluation. Security and all third-party services need implementation before real-world use.</div></section></div></div>`}
function render(){if(!state.data)return;document.body.classList.toggle('customer-mode',['storefront','quick-quote','customer-hub','homeowner'].includes(state.view));const views={overview:renderControlTower,storefront:renderStorefront,'quick-quote':()=>FrameOpsCheckout.renderQuote(),'customer-hub':()=>FrameOpsCheckout.renderHub(),'quote-operations':()=>FrameOpsCheckout.renderOps(),'demo-journey':()=>FrameOpsDemoJourney.experience(),'business-settings':()=>FrameOpsBusinessSettings.renderSettings(),frontdesk:()=>opsModuleRecords('frontdesk'),leads:()=>opsModuleRecords('leads'),measurements:()=>opsModuleRecords('measurements'),vendors:()=>opsModuleRecords('vendors'),installation:()=>opsModuleRecords('installation'),financing:()=>opsModuleRecords('financing'),accounting:()=>opsModuleRecords('accounting'),warranty:()=>opsModuleRecords('warranty'),'customer-service':()=>opsModuleRecords('customer-service'),documents:()=>opsModuleRecords('documents'),jobs:renderJobs,tasks:renderTasks,notifications:renderNotifications,job:renderJob,homeowner:()=>FrameOpsCheckout.renderHub(),workflow:renderWorkflow};$('#app').innerHTML=(views[state.view]||renderControlTower)();if(['overview','financing','accounting','vendors','installation','frontdesk','leads','measurements','customer-service','warranty','notifications'].includes(state.view)){const demo=FrameOpsCheckout.read();const order=demo.orders.find(o=>o.id===demo.selectedOrder)||demo.orders.at(-1);if(order){const role=state.role;const unread=order.notifications.filter(n=>n.role===role&&!n.read).length;const el=document.createElement('div');el.className='sim-mini-banner';el.innerHTML=`<div><strong>Customer order ${esc(order.id)} · ${esc(order.status)}</strong><span>${unread} simulated notifications for ${esc(role)} · One shared browser-local quote, schedule and project record</span></div><button data-nav="quote-operations" type="button">Open quote and schedule console →</button>`;$('#app').prepend(el)}}}

const schemas={
  add_opening:{title:'Add measured window / door',desc:'Enter one opening type, installation location and field dimensions. Before proposal submission only.',fields:[['room','Room / location','text',true],['product_type','Opening type','select',['Window','Exterior door','Patio door','Other']],['quantity','Quantity of identical openings','number',true],['width','Measured width (inches)','number',true],['height','Measured height (inches)','number',true],['frame','Frame / material','text',false],['glazing','Glass / glazing type','text',false],['unit_price','Estimated product unit price ($)','number',false],['notes','Site notes and constraints','textarea',false]]},
  newLead:{title:'Create homeowner lead',desc:'Public shared demo: use made-up names and addresses only. The new lead generates a front desk qualification task.',fields:[['homeowner','Homeowner full name','text',true],['phone','Phone number','tel',false],['email','Email address','email',false],['address','Property address','text',true],['service_type','Products / requested work','text',true],['lead_source','Lead source','select',['Website','Phone','Showroom','Referral','Google Search','Partner','Other']],['assigned_sales','Salesperson','select',['Unassigned','Jordan Lee','Avery Kim']],['priority','Priority','select',['Normal','High','Urgent']],['notes','Inquiry notes','textarea',false]]},
  qualify:{title:'Qualify lead',desc:'Confirm customer details and hand the job to sales.',fields:[]},
  schedule_measurement:{title:'Book site measurement',desc:'Assign a field measurement visit and notify the technician.',fields:[['date','On-site appointment date','date',true]]},
  complete_measurement:{title:'Record actual measurements',desc:'Describe opening count, widths / heights, types and site exceptions.',fields:[['notes','Verified field dimensions and site notes','textarea',true]]},
  send_proposal:{title:'Send homeowner proposal',desc:'Enter the complete quoted amount, including products, labor and approved extras.',fields:[['amount','Quoted contract total ($)','number',true]]},
  accept_proposal:{title:'Approve homeowner proposal',desc:'Demonstration acceptance only; connect verified homeowner approval in production.',fields:[]},
  sign_contract:{title:'Record contract acceptance',desc:'This action simulates a signed contract, not an enforceable e-signature.',fields:[['deposit','Required deposit ($)','number',true],['financing_type','Funding choice','select',['Customer pay','Financing requested']]]},
  finance_update:{title:'Update financing decision',desc:'Record an external lender status. This does not submit an application.',fields:[['status','Lender decision','select',['Pending','Approved','Declined']]]},
  record_payment:{title:'Record cleared payment',desc:'Accountant records funds already received. No money is actually transferred.',fields:[['amount','Amount received ($)','number',true],['kind','Payment category','select',['Deposit','Progress','Final','Financing disbursement','Other']],['method','Payment method','select',['Bank transfer','Check','Card - externally processed','Financing payout','Manual record']],['reference','Transaction reference','text',false]]},
  place_order:{title:'Issue vendor purchase order',desc:'Capture supplier order information and notify the vendor queue.',fields:[['vendor','Supplier / vendor name','text',true],['po','Purchase order ID','text',true],['eta','Expected arrival','date',true]]},
  materials_received:{title:'Confirm materials receipt',desc:'Confirm the ordered doors / windows have been received and inspected.',fields:[]},
  schedule_install:{title:'Schedule installation',desc:'Materials, required permits and insurance checks must be ready.',fields:[['date','Installation date','date',true]]},
  installation_complete:{title:'Record installation completion',desc:'Report work performed and any punch list or customer constraints.',fields:[['notes','Installation report','textarea',true]]},
  qa_passed:{title:'Approve quality walkthrough',desc:'Record inspection, operating checks, cleanup and homeowner handoff.',fields:[['notes','QA inspection / punch list notes','textarea',true]]},
  close_job:{title:'Close job and activate warranty',desc:'Requires site QA passed and recorded payment of full contract total.',fields:[['terms','Warranty coverage / duration from contract','textarea',true]]},
  insurance_update:{title:'Verify insurance documentation',desc:'Track contractor or subcontractor certificate of insurance (COI).',fields:[['status','COI status','select',['Not required','Pending','Verified']]]},
  permit_update:{title:'Record permit readiness',desc:'Mark whether a permit is required and cleared before installation.',fields:[['status','Permit status','select',['Not required','Pending','Approved']]]},
  service_request:{title:'Create warranty service request',desc:'Create a tracked service work item linked to this original job.',fields:[['notes','Describe the issue / requested service','textarea',true]]},
  note:{title:'Add job note',desc:'Record a team communication in the shared project timeline.',fields:[['notes','Internal note / status update','textarea',true]]},
  set_priority:{title:'Set job priority',desc:'Update urgency without changing the workflow.',fields:[['priority','Priority','select',['Normal','High','Urgent']]]},
  upload:{title:'Upload job document',desc:'Uploads are disabled on the public demo to protect visitors. Local development supports PDF, PNG, JPG, DOCX, TXT, CSV up to 4 MB.',fields:[['doc_type','Document category','select',['Photos','Measurements','Proposal','Contract','Purchase order','Permit','Insurance','Financing','Invoice','Warranty','Other']],['file','Select local file','file',true]]}
};
function modalHtml(code){const s=schemas[code];if(!s)return '';const isNew=code==='newLead';const title=s.title;return `<div class="modal-scrim" id="modal-scrim"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div class="modal-head"><div><h2 id="modal-heading">${esc(title)}</h2><p>${esc(s.desc)}</p></div><button class="modal-close" data-modal-close aria-label="Close">×</button></div><form id="action-form" data-mode="${code}" class="modal-body"><div class="form-error" id="form-error"></div>${s.fields.length?s.fields.map(([name,label,type,required])=>`<div class="form-field"><label for="fld-${name}">${esc(label)} ${required===true?'<span style="color:#bf5365">*</span>':''}</label>${type==='textarea'?`<textarea id="fld-${name}" name="${name}" ${required===true?'required':''} placeholder="Enter details"></textarea>`:type==='select'?`<select id="fld-${name}" name="${name}">${required.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`:`<input id="fld-${name}" type="${type}" name="${name}" ${required===true?'required':''} ${type==='number'?'min="0" step="0.01"':''} ${type==='date'?`min="${today()}"`:''} ${type==='file'?'accept=".pdf,.png,.jpg,.jpeg,.docx,.txt,.csv"':''}>`}</div>`).join(''):`<div class="notice blue">This will move the job to the next stage and generate the corresponding team assignment and notifications.</div>`}<div class="modal-actions"><button type="button" class="button" data-modal-close>Cancel</button><button type="submit" class="button primary" id="submit-action">${isNew?'Create lead':code==='upload'?'Upload document':'Confirm & save'}</button></div></form></section></div>`}
function modal(code){$('#modal-root').innerHTML=modalHtml(code);$('#modal-root').querySelector('input,select,textarea')?.focus()}
function closeModal(){$('#modal-root').innerHTML=''}
async function submitAction(form){const code=form.dataset.mode;const button=$('#submit-action');const error=$('#form-error');error.style.display='none';button.disabled=true;button.textContent='Saving…';const data=Object.fromEntries(new FormData(form).entries());try{
 if(code==='newLead'){const r=await api('/api/jobs',{method:'POST',body:JSON.stringify({...data,actor:state.role})});closeModal();await load();await openJob(r.id);toast('New lead created. Front desk task assigned.');return}
 if(code==='upload'){const f=data.file;if(!f||!f.size)throw new Error('Select a document to upload');if(f.size>4e6)throw new Error('Maximum file size is 4 MB');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read selected file'));reader.readAsDataURL(f)});await api('/api/jobs/'+state.job.id+'/upload',{method:'POST',body:JSON.stringify({name:f.name,base64:encoded,doc_type:data.doc_type,actor:state.role})});toast('Document added to job record.')}
 else {const actor=state.view==='homeowner'?'Homeowner':state.role;const id=state.view==='homeowner'?state.homeownerId:state.job.id;await api('/api/jobs/'+id+'/action',{method:'POST',body:JSON.stringify({action:code,fields:data,actor})});toast(actionNames[code]+' saved.')}
 closeModal();const wasHome=state.view==='homeowner';const jobId=wasHome?state.homeownerId:state.job?.id;state.data=await api('/api/bootstrap');if(state.view==='job'&&jobId)state.job=await api('/api/jobs/'+jobId);updateHeader();render();
 }catch(e){error.textContent=e.message;error.style.display='block';button.disabled=false;button.textContent=code==='newLead'?'Create lead':code==='upload'?'Upload document':'Confirm & save'}
}
// Delegation makes all dynamically rendered controls functional.
document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();go(nav.dataset.nav);return}
 const job=e.target.closest('[data-job]');if(job){e.preventDefault();await openJob(job.dataset.job);return}
 const modalTrigger=e.target.closest('[data-modal]');if(modalTrigger){modal(modalTrigger.dataset.modal);return}
 const act=e.target.closest('[data-action]');if(act){modal(act.dataset.action);return}
 const homeAct=e.target.closest('[data-homeowner-action]');if(homeAct){modal(homeAct.dataset.homeownerAction);return}
 const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return}
 const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return}
 const close=e.target.closest('[data-modal-close]');if(close||e.target.id==='modal-scrim'){closeModal();return}
 const read=e.target.closest('[data-read-notifications]');if(read){try{await api('/api/notifications/read',{method:'POST',body:JSON.stringify({actor:state.role})});await load();toast('Notifications marked as read.')}catch(err){toast(err.message,true)}return}
});
document.addEventListener('submit',e=>{if(e.target.id==='action-form'){e.preventDefault();submitAction(e.target)}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){state.search=e.target.value;const value=e.target.value.toLowerCase();document.querySelectorAll('.data-table tbody tr').forEach(tr=>{tr.style.display=tr.textContent.toLowerCase().includes(value)?'':'none'})}});
document.addEventListener('change',e=>{if(e.target.id==='homeowner-select'){state.homeownerId=e.target.value;render()}});
$('#role-select').addEventListener('change',e=>{state.role=e.target.value;updateHeader();render()});
$('#top-notifications').addEventListener('click',()=>go('notifications'));
$('#mobile-menu').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#overlay')?.classList.toggle('open')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
const overlay=document.createElement('div');overlay.id='overlay';overlay.className='mobile-overlay';document.body.append(overlay);overlay.addEventListener('click',()=>{$('#sidebar').classList.remove('open');overlay.classList.remove('open')});
load().catch(err=>{$('#app').innerHTML=`<div class="page"><div class="notice">Unable to load the prototype: ${esc(err.message)}. Start the Python server and reload this page.</div></div>`});
